                props[self.s(nameoff)] = val
            elif tok == FDT_END_NODE:
                yield '/'.join(stack), props
                stack.pop(); props = {}
            elif tok == FDT_END:
                break
    @staticmethod
    def u32s(v): return list(struct.unpack('>%dI'%(len(v)//4), v[:len(v)//4*4]))
    @staticmethod
    def strs(v): return [x.decode() for x in v.split(b'\0') if x]
