static int rk3576_i2c_start(struct rk3576_i2c_priv_s *priv, uint32_t mode)
{
  uint32_t con;

  i2c_putreg(priv, RK3576_I2C_IPD, I2C_INT_ALL);

  con = I2C_CON_EN | mode | I2C_CON_START | I2C_CON_ACT2NAK;
